using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
using QuietCare;

internal static class UiTests {
    static int passed,failed;
    static string previewDirectory;
    static void Preview(MainWindow window,string name){if(String.IsNullOrEmpty(previewDirectory))return;Layout(window);var root=(FrameworkElement)window.Content;var image=new System.Windows.Media.Imaging.RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);image.Render(root);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(image));Directory.CreateDirectory(previewDirectory);using(var stream=File.Create(Path.Combine(previewDirectory,name+".png")))encoder.Save(stream);}
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static void Test(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex);}}
    static void Pump(int ms){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
    static void Layout(MainWindow window){var root=(FrameworkElement)window.Content;root.Measure(new Size(980,650));root.Arrange(new Rect(0,0,980,650));root.UpdateLayout();Pump(20);}
    static IEnumerable<DependencyObject> Descendants(DependencyObject root){if(root==null)yield break;yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Descendants(VisualTreeHelper.GetChild(root,i)))yield return child;}
    sealed class BoostHost : IBoostRuntime {
        public int Trimmed;
        public List<BoostProcess> Capture(){return new List<BoostProcess>{new BoostProcess{App=new AppProcess{Id=999001,Name="UIBackgroundFixture",Path="C:\\Fixture\\UIBackgroundFixture.exe",Bytes=100*1024*1024,Started=new DateTime(2020,1,1,0,0,0,DateTimeKind.Utc)}}};}
        public int Foreground(){return 0;}public AudioActivity Audio(){return new AudioActivity{Verified=true};}public void Trim(AppProcess p){if(p.Id!=999001)throw new Exception("Unexpected process");Trimmed++;}public ulong Available(){return 2UL*1024*1024*1024;}
    }
    sealed class UpdateHost : IUpdateService {
        public int Checked,Downloaded;
        public Task<UpdateRelease> Check(bool preview,CancellationToken cancel){Checked++;ReleaseVersion version;ReleaseVersion.TryParse("v9.0.0",out version);return Task.FromResult(new UpdateRelease{Version=version,PageUrl=UpdatePolicy.Page(version.Tag),Notes="<script>plain text only</script>",Installer=new UpdateAsset{Url="https://github.com/"+AppInfo.Repository+"/releases/download/v9.0.0/QuietCare-Setup.exe",Sha256=new string('a',64),Size=2}});}
        public Task<VerifiedInstaller> Download(UpdateRelease release,IProgress<int> progress,CancellationToken cancel){Downloaded++;throw new Exception("UI test must not download or install");}
    }
    sealed class CareHost : ICareChecks {
        public readonly ManualResetEventSlim Started=new ManualResetEventSlim(),Continue=new ManualResetEventSlim();public int Count;
        public CareCheckResult Check(string id,Action<string,string> progress,CancellationToken cancel){Count++;progress("Observed synthetic UI fixture",id);Started.Set();if(!Continue.Wait(5000,cancel))throw new TimeoutException("UI fixture gate expired");return new CareCheckResult{Summary="Observed fixture; no changes applied."};}
    }
    [STAThread]static int Main(string[] args){
        previewDirectory=args.Length>1?args[1]:null;State.DirectoryPath=Path.Combine(args[0],"UiState");var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Theme.Install(app);
        var settings=new Settings{ShowWidget=false,CloseToTray=false};var boost=new BoostHost();var updater=new UpdateHost();var care=new CareHost();var main=new MainWindow(settings,true,boost,updater,care);app.MainWindow=main;
        Test("Cold monitor/tray launch does not construct the main UI",()=>{main.StartInTray();Check(!main.ShellBuilt,"Main UI eagerly created");Check(!main.IsVisible&&!main.SamplingScheduled,"Hidden app is polling");});
        var widget=new Widget(main,settings);
        Test("Floating Boost runs directly without opening any chooser",()=>{widget.BoostControl.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));for(int i=0;i<50&&boost.Trimmed==0;i++)Pump(50);Check(boost.Trimmed==1,"Button did not invoke direct Boost");Check(!main.ShellBuilt&&!main.IsVisible,"Boost opened the main chooser");});
        Test("Boost results expose measurements and skipped reasons without fake savings",()=>{for(int i=0;i<50&&main.LastBoost==null;i++)Pump(20);Check(main.LastBoost!=null&&main.LastBoost.Trimmed==1&&main.LastBoost.ObservedReductions==0,"Unmeasured fixture labeled as savings");main.InspectPage("Boost results");Layout(main);Preview(main,"Boost-results-fixture");Check(Descendants(main.PageView).OfType<TextBlock>().Any(t=>t.Text.Contains("Available physical RAM")),"Missing before/after physical RAM");});
        Test("Transparent widget stays compact at maximum values",()=>{widget.Update(new Snapshot{Cpu=100,Gpu=100,Ram=100,Available=1024,Total=4096});var root=(FrameworkElement)widget.Content;root.Measure(new Size(double.PositiveInfinity,double.PositiveInfinity));root.Arrange(new Rect(root.DesiredSize));root.UpdateLayout();Check(widget.AllowsTransparency,"Not a transparent window");Check(root.DesiredSize.Width<=240&&root.DesiredSize.Height<=32,"Widget too large: "+root.DesiredSize);var text=Descendants(root).OfType<TextBlock>().Select(t=>t.Text).First(t=>t.Contains("CPU")&&t.Contains("GPU")&&t.Contains("RAM"));Check(text.IndexOf("CPU")<text.IndexOf("GPU")&&text.IndexOf("GPU")<text.IndexOf("RAM"),"Wrong order");Check(((SolidColorBrush)((Border)root).Background).Color.A<255,"Background opaque");});
        Test("Unknown GPU values render a dash and no bogus zero",()=>{widget.Update(new Snapshot{Cpu=1,Gpu=null,Ram=50});var texts=Descendants((FrameworkElement)widget.Content).OfType<TextBlock>().Select(t=>t.Text);Check(texts.Any(t=>t.Contains("GPU —")),"Missing GPU was not shown as unavailable");});
        Test("No update request occurs on default cold startup",()=>Check(updater.Checked==0&&!settings.CheckUpdatesWeekly,"Unexpected background network check"));
        Test("SCAN opens live steps and preserves observations for review",()=>{main.InspectPage("Overview");Layout(main);Preview(main,"Care-home-render");var scan=Descendants(main.PageView).OfType<Button>().Single(b=>System.Windows.Automation.AutomationProperties.GetName(b)=="Start Care scan");scan.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));for(int i=0;i<30&&!care.Started.IsSet;i++)Pump(20);Check(main.CareScanRunning&&main.CurrentPage=="Care scan","No live scan page");Layout(main);Preview(main,"Care-live-fixture");Check(Descendants(main.PageView).OfType<Button>().Any(b=>Object.Equals(b.Content,"Stop scan")&&b.IsEnabled),"Stop unavailable during scan");care.Continue.Set();for(int i=0;i<60&&main.CareScanRunning;i++)Pump(20);Check(!main.CareScanRunning&&main.LastCareReport.Results.Count==6&&care.Count==6,"Missing observed results");main.InspectPage("Care scan");Layout(main);Check(Descendants(main.PageView).OfType<Button>().Any(b=>Object.Equals(b.Content,"Review temp candidates")),"No review path");});
        string[] pages={"Overview","Care scan","Speed Up","Protect","Updates","Processes & RAM","Boost results","Startup manager","Cleanup","File tools","Installed apps","Toolbox","System information","Recovery","Settings"};
        foreach(string page in pages){string name=page;Test("Layout and controls: "+name,()=>{main.InspectPage(name);var root=(FrameworkElement)main.Content;root.Measure(new Size(980,650));root.Arrange(new Rect(0,0,980,650));root.UpdateLayout();Pump(120);var view=(ScrollViewer)main.PageView;Check(view.Content!=null,"Empty page");Check(Descendants(view).OfType<Button>().Any(),"Page has no actions");Check(view.ExtentWidth<=view.ViewportWidth+2,"Horizontal content overflow: "+view.ExtentWidth+" / "+view.ViewportWidth);Check(main.CurrentPage==name,"Navigation mismatch");});}
        Test("Title strip removed; transparent caption controls preserve page space",()=>{main.InspectPage("Overview");var canvas=(Grid)((Border)main.Content).Child;Check(canvas.RowDefinitions.Count==2&&canvas.RowDefinitions[0].Height.IsStar,"Separate title row still reserves space");var controls=Descendants(canvas).OfType<StackPanel>().Single(x=>x.Name=="CaptionControls");Check(controls.Children.Count==4&&((SolidColorBrush)controls.Background).Color.A==0,"Caption overlay is opaque or incomplete");Check(controls.Children.OfType<Button>().All(x=>((SolidColorBrush)x.Background).Color.A==0),"Caption button background is opaque");Check(Descendants(canvas).OfType<Border>().Any(x=>x.Name=="WindowDragRegion"&&x.Height>=12),"Window has no draggable region");});
        Test("All pages fit the minimum supported window width",()=>{foreach(string page in pages){main.InspectPage(page);var root=(FrameworkElement)main.Content;root.Measure(new Size(858,608));root.Arrange(new Rect(0,0,858,608));root.UpdateLayout();var view=(ScrollViewer)main.PageView;Check(view.ViewportWidth>600,"Content area too narrow: "+page);Check(view.ExtentWidth<=view.ViewportWidth+2,"Horizontal overflow at minimum width: "+page);var controls=Descendants(root).OfType<StackPanel>().Single(x=>x.Name=="CaptionControls");var bounds=controls.TransformToAncestor(root).TransformBounds(new Rect(controls.RenderSize));Check(bounds.Right<=root.ActualWidth+1&&bounds.Top>=0,"Caption controls clipped");}});
        Test("Check for updates uses the injected host and never auto-downloads",()=>{main.InspectPage("Updates");Layout(main);Preview(main,"Updates-render");var button=Descendants(main.PageView).OfType<Button>().Single(b=>Object.Equals(b.Content,"Check for updates"));button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));for(int i=0;i<30&&main.UpdateRunning;i++)Pump(20);Check(updater.Checked==1&&updater.Downloaded==0&&main.UpdateMessage.Contains("v9.0.0"),"Manual update flow failed");Check(Descendants(main.PageView).OfType<TextBox>().Any(t=>t.IsReadOnly&&t.Text=="<script>plain text only</script>"),"Notes are not plain text");Check(Descendants(main.PageView).OfType<Button>().Any(b=>Object.Equals(b.Content,"Open installer")&&!b.IsEnabled),"Installer enabled before verification");button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(updater.Checked==1,"Cooldown failed");});
        Test("Settings exposes opt-in startup checks and preview channel",()=>{main.InspectPage("Settings");Layout(main);var checks=Descendants(main.PageView).OfType<CheckBox>().ToList();Check(checks.Any(c=>Object.Equals(c.Content,"Check at startup, at most once a week")&&c.IsChecked==false),"Weekly default missing");Check(checks.Any(c=>Object.Equals(c.Content,"Include preview releases")&&c.IsChecked==true),"Preview channel missing");Check(checks.Any(c=>Object.Equals(c.Content,"Include OS-background browser renderers")&&c.IsChecked==true),"Browser control missing");});
        Test("Data tables sort memory by byte count and expose tooltips",()=>{main.InspectPage("Processes & RAM");var root=(FrameworkElement)main.Content;root.Measure(new Size(980,650));root.Arrange(new Rect(0,0,980,650));root.UpdateLayout();var grid=Descendants(main.PageView).OfType<DataGrid>().Single();Check(grid.Columns.Any(c=>c.Header.ToString()=="RAM"&&c.SortMemberPath=="Bytes"),"RAM sorting is lexical");Check(grid.Columns.OfType<DataGridTextColumn>().All(c=>c.ElementStyle.Setters.OfType<Setter>().Any(s=>s.Property==FrameworkElement.ToolTipProperty)),"Missing full-value tooltips");});
        widget.AllowClose=true;widget.Close();main.Exit();Console.WriteLine("UI RESULT "+passed+" passed / "+failed+" failed");return failed==0?0:1;
    }
}
